#include <iostream>
#include <vector>
#include <array>
#include "../earcut.hpp"

int main(int argc, char* argv[]) {
    int n = 7;
    if (argc > 1) {
        n = std::atoi(argv[1]);
    }

    std::vector<std::vector<std::array<double, 2>>> polygon;
    std::vector<std::array<double, 2>> spiral;

    for (int i = 0; i < n * 2; i++) {
        double t = double(i) / (n * 2);
        double radius = t;
        double angle = 4.0 * M_PI * t;
        spiral.push_back({radius * std::cos(angle), radius * std::sin(angle)});
    }

    polygon.push_back(spiral);

    auto indices = mapbox::earcut<uint32_t>(polygon);

    for (auto idx : indices) {
        std::cout << idx << " ";
    }
    return 0;
}


